111: export function isSafeHref(url: string): boolean {
112:   try {
113:     // No base: a source link is always absolute, so a relative string is not
114:     // one either, and resolving it against our own origin would invent a link
115:     // to ourselves out of whatever the crawler happened to store.
116:     const scheme = new URL(url).protocol;
117:     return scheme === 'http:' || scheme === 'https:';
118:   } catch {
119:     return false;
120:   }
121: }
